class OrderManagementSystem {
    unordered_map<int, pair<string,int>> info;
    unordered_map<string, unordered_set<int>> groups;
    static string key(const string& t, int p){ return t + "#" + to_string(p); }
public:
    OrderManagementSystem() {}
    void addOrder(int orderId, string orderType, int price) {
        info[orderId] = {orderType, price};
        groups[key(orderType, price)].insert(orderId);
    }
    void modifyOrder(int orderId, int newPrice) {
        auto [t, p] = info[orderId];
        groups[key(t, p)].erase(orderId);
        info[orderId].second = newPrice;
        groups[key(t, newPrice)].insert(orderId);
    }
    void cancelOrder(int orderId) {
        auto [t, p] = info[orderId];
        groups[key(t, p)].erase(orderId);
        info.erase(orderId);
    }
    vector<int> getOrdersAtPrice(string orderType, int price) {
        return vector<int>(groups[key(orderType, price)].begin(), groups[key(orderType, price)].end());
    }
};

