class OrderManagementSystem {
    private Map<Integer, Object[]> info = new HashMap<>();
    private Map<String, Set<Integer>> groups = new HashMap<>();
    public OrderManagementSystem() {}
    private String key(String t, int p){ return t + "#" + p; }
    public void addOrder(int orderId, String orderType, int price) {
        info.put(orderId, new Object[]{orderType, price});
        groups.computeIfAbsent(key(orderType, price), k -> new HashSet<>()).add(orderId);
    }
    public void modifyOrder(int orderId, int newPrice) {
        Object[] o = info.get(orderId);
        groups.get(key((String)o[0], (Integer)o[1])).remove(orderId);
        o[1] = newPrice;
        groups.computeIfAbsent(key((String)o[0], newPrice), k -> new HashSet<>()).add(orderId);
    }
    public void cancelOrder(int orderId) {
        Object[] o = info.remove(orderId);
        groups.get(key((String)o[0], (Integer)o[1])).remove(orderId);
    }
    public List<Integer> getOrdersAtPrice(String orderType, int price) {
        return new ArrayList<>(groups.getOrDefault(key(orderType, price), Collections.emptySet()));
    }
}

