var OrderManagementSystem = function() {
    this.info = new Map();
    this.groups = new Map();
};
OrderManagementSystem.prototype.k = function(t, p){ return t + '#' + p; };
OrderManagementSystem.prototype.addOrder = function(orderId, orderType, price) {
    this.info.set(orderId, [orderType, price]);
    const k = this.k(orderType, price);
    if (!this.groups.has(k)) this.groups.set(k, new Set());
    this.groups.get(k).add(orderId);
};
OrderManagementSystem.prototype.modifyOrder = function(orderId, newPrice) {
    const [t, p] = this.info.get(orderId);
    this.groups.get(this.k(t, p)).delete(orderId);
    this.info.set(orderId, [t, newPrice]);
    const nk = this.k(t, newPrice);
    if (!this.groups.has(nk)) this.groups.set(nk, new Set());
    this.groups.get(nk).add(orderId);
};
OrderManagementSystem.prototype.cancelOrder = function(orderId) {
    const [t, p] = this.info.get(orderId);
    this.groups.get(this.k(t, p)).delete(orderId);
    this.info.delete(orderId);
};
OrderManagementSystem.prototype.getOrdersAtPrice = function(orderType, price) {
    const g = this.groups.get(this.k(orderType, price));
    return g ? [...g] : [];
};
